param([Parameter(Mandatory=$true)][string]$ShareGrantPath,[Parameter(Mandatory=$true)][string]$ActorId,[Parameter(Mandatory=$true)][string]$Reason,[Parameter(Mandatory=$true)][string]$GrantId,[Parameter(Mandatory=$true)][string]$TraceId,[switch]$PassThru)
$ErrorActionPreference='Stop';$projectRoot=(Resolve-Path (Join-Path $PSScriptRoot '..\..')).Path;$root=[IO.Path]::GetFullPath((Join-Path $projectRoot '.qianlima/run-traces/enterprise-memory/share-grants')).TrimEnd('\','/')+[IO.Path]::DirectorySeparatorChar;$ledger=Join-Path $projectRoot '.qianlima/run-traces/enterprise-memory/share-revocations.jsonl';function Emit([hashtable]$Value,[int]$Code=0){if($PassThru){$Value|ConvertTo-Json -Depth 10}else{$Value|Format-List};if($Code-ne0){exit $Code}}
try{$full=(Resolve-Path -LiteralPath $ShareGrantPath -ErrorAction Stop).Path;$share=Get-Content -LiteralPath $full -Raw -Encoding UTF8|ConvertFrom-Json}catch{Emit ([ordered]@{status='blocked';reason='share_grant_not_found_or_invalid';revoked=$false}) 1};if(-not$full.StartsWith($root,[StringComparison]::OrdinalIgnoreCase)){Emit ([ordered]@{status='blocked';reason='share_grant_outside_governed_root';revoked=$false}) 1};if(Test-Path -LiteralPath $ledger){foreach($line in @(Get-Content -LiteralPath $ledger -Encoding UTF8)){if($line){try{$old=$line|ConvertFrom-Json;if([string]$old.share_grant_id-eq[string]$share.share_grant_id){Emit ([ordered]@{status='revoked';reason='already_revoked';revoked=$true;record_mutated=$false})}}catch{Emit ([ordered]@{status='blocked';reason='share_revocation_ledger_invalid';revoked=$false}) 1}}}}
$event=[ordered]@{schema_version=1;revocation_id=[Guid]::NewGuid().ToString('n');share_grant_id=[string]$share.share_grant_id;memory_id=[string]$share.memory_id;actor_id=$ActorId;reason=$Reason;revoked_at=[DateTime]::UtcNow.ToString('o')};New-Item -ItemType Directory -Path (Split-Path -Parent $ledger) -Force|Out-Null;[IO.File]::AppendAllText($ledger,(($event|ConvertTo-Json -Compress)+[Environment]::NewLine),[Text.UTF8Encoding]::new($false));$audit=Join-Path $PSScriptRoot 'append-enterprise-audit-event.ps1';try{& $audit -EventType memory_share_revoked -Decision revoke -TenantId ([string]$share.tenant_id) -OrganizationId ([string]$share.organization_id) -UserId $ActorId -AgentId ([string]$share.source_agent_id) -AgentVersion 'memory-share-v1' -TaskId ([string]$share.task_id) -GrantId $GrantId -TraceId $TraceId -PolicyVersion '2.14.0' -DataRefs @((('memory://'+[string]$share.memory_id)),(('memory-cube://'+[string]$share.cube_id))) -EvidenceRefs ('memory-share-revocation://'+$event.revocation_id) -PassThru|Out-Null}catch{Emit ([ordered]@{status='blocked';reason='share_revocation_audit_failed';revoked=$true}) 1};Emit ([ordered]@{status='revoked';revoked=$true;share_grant_id=[string]$share.share_grant_id;record_mutated=$false;external_calls=$false})
